package com.dongwon.sleeptimeline;
import android.content.*;import android.database.*;import android.database.sqlite.*;import org.json.*;import java.util.*;
public class Store extends SQLiteOpenHelper {
 public Store(Context c){super(c,"sleep.db",null,1);}
 public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE records(id INTEGER PRIMARY KEY,start INTEGER NOT NULL,end INTEGER NOT NULL,state TEXT NOT NULL,kind TEXT NOT NULL,zone TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',UNIQUE(start,end))");}
 public void onUpgrade(SQLiteDatabase d,int a,int b){}
 public synchronized JSONArray all() throws Exception {JSONArray a=new JSONArray();Cursor c=getReadableDatabase().rawQuery("SELECT * FROM records WHERE state!='dismissed' AND (state='confirmed' OR end-start>="+SleepLogic.MIN_CANDIDATE+") ORDER BY end DESC",null);try{while(c.moveToNext())a.put(new JSONObject().put("id",c.getLong(0)).put("start",c.getLong(1)).put("end",c.getLong(2)).put("state",c.getString(3)).put("kind",c.getString(4)).put("zone",c.getString(5)).put("note",c.getString(6)));}finally{c.close();}return a;}
 private boolean conflict(SQLiteDatabase d,long s,long e,long id){Cursor c=d.rawQuery("SELECT id FROM records WHERE state='confirmed' AND id!=? AND start<? AND end>?",new String[]{""+id,""+e,""+s});try{return c.moveToFirst();}finally{c.close();}}
 public synchronized void propose(List<SleepLogic.Gap> gaps,long now){SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{for(SleepLogic.Gap g:gaps){if(conflict(d,g.start,g.end,-1)||similar(d,g.start,g.end))continue;d.delete("records","state='candidate' AND start>=? AND end<=?",new String[]{""+g.start,""+g.end});/* 더 긴 후보 안에 들어가는 예전 쪼개진 후보는 지운다. */ContentValues v=new ContentValues();v.put("start",g.start);v.put("end",g.end);v.put("state","candidate");v.put("kind","sleep");v.put("zone",TimeZone.getDefault().getID());d.insertWithOnConflict("records",null,v,SQLiteDatabase.CONFLICT_IGNORE);}d.delete("records","state!='confirmed' AND end<?",new String[]{""+(now-30L*86400000)});d.setTransactionSuccessful();}finally{d.endTransaction();}}
 // 이미 있는 후보·삭제한 후보와 양방향 80% 이상 겹치면 같은 구간으로 보고 다시 만들지 않는다.
 private boolean similar(SQLiteDatabase d,long start,long end){Cursor c=d.rawQuery("SELECT start,end FROM records WHERE state!='confirmed' AND start<? AND end>?",new String[]{""+end,""+start});try{while(c.moveToNext()){long s=c.getLong(0),e=c.getLong(1),overlap=Math.min(end,e)-Math.max(start,s);if(overlap>0&&overlap>=.8*(end-start)&&overlap>=.8*(e-s))return true;}return false;}finally{c.close();}}
 public synchronized void save(JSONObject r) throws Exception {SQLiteDatabase d=getWritableDatabase();long s=r.getLong("start"),e=r.getLong("end"),id=r.optLong("id",-1);String kind=r.optString("kind","sleep"),note=r.optString("note","");if(!SleepLogic.valid(s,e,System.currentTimeMillis()))throw new Exception("시작·종료 시간을 확인해 줘. 미래 시간과 24시간 넘는 기록은 저장할 수 없어.");if(!kind.equals("sleep")&&!kind.equals("nap"))throw new Exception("기록 종류가 올바르지 않아.");if(note.length()>160)throw new Exception("메모는 160자까지 입력할 수 있어.");d.beginTransaction();try{if(id<=0){Cursor existing=d.rawQuery("SELECT id FROM records WHERE start=? AND end=? AND state!='confirmed'",new String[]{""+s,""+e});try{if(existing.moveToFirst())id=existing.getLong(0);}finally{existing.close();}}if(conflict(d,s,e,id))throw new Exception("이미 저장한 수면 시간과 겹쳐. 기존 기록을 수정해 줘.");ContentValues v=new ContentValues();v.put("start",s);v.put("end",e);v.put("state","confirmed");v.put("kind",kind);v.put("zone",r.optString("zone",TimeZone.getDefault().getID()));v.put("note",note);if(id>0){if(d.update("records",v,"id=?",new String[]{""+id})!=1)throw new Exception("이 기록을 찾을 수 없어.");}else{if(d.insert("records",null,v)==-1)throw new Exception("동일한 기록이 있어.");}ContentValues dismissed=new ContentValues();dismissed.put("state","dismissed");d.update("records",dismissed,"state='candidate' AND start<? AND end>?",new String[]{""+e,""+s});d.setTransactionSuccessful();}finally{d.endTransaction();}}
 public synchronized void remove(long id){ContentValues v=new ContentValues();v.put("state","dismissed");getWritableDatabase().update("records",v,"id=?",new String[]{""+id});}
 public synchronized boolean isDismissed(long start,long end){
  Cursor c=getReadableDatabase().rawQuery("SELECT start,end FROM records WHERE state='dismissed' AND start<? AND end>?",new String[]{""+end,""+start});
  try{while(c.moveToNext()){long s=c.getLong(0),e=c.getLong(1),overlap=Math.min(end,e)-Math.max(start,s);if(overlap>0&&overlap>=.8*(end-start)&&overlap>=.8*(e-s))return true;}return false;}finally{c.close();}
 }
 public synchronized JSONObject backup()throws Exception{JSONArray out=new JSONArray(),rows=all();for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);if(r.getString("state").equals("confirmed"))out.put(r);}return new JSONObject().put("schema",1).put("app","SleepTimeline").put("exportedAt",System.currentTimeMillis()).put("records",out);}
 public synchronized int restore(String input)throws Exception{JSONObject obj=new JSONObject(input);if(obj.optInt("schema")!=1||!obj.optString("app").equals("SleepTimeline"))throw new Exception("수면 타임라인 백업 파일이 아니야.");JSONArray rows=obj.getJSONArray("records");if(rows.length()>10000)throw new Exception("백업 기록이 너무 많아.");List<JSONObject> clean=new ArrayList<JSONObject>();for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);if(!SleepLogic.valid(r.getLong("start"),r.getLong("end"),System.currentTimeMillis())||!r.optString("state").equals("confirmed")||(!r.optString("kind").equals("sleep")&&!r.optString("kind").equals("nap"))||r.optString("note").length()>160)throw new Exception("백업 안에 올바르지 않은 기록이 있어.");clean.add(r);}Collections.sort(clean,new Comparator<JSONObject>(){public int compare(JSONObject a,JSONObject b){return Long.compare(a.optLong("start"),b.optLong("start"));}});for(int i=1;i<clean.size();i++)if(clean.get(i).optLong("start")<clean.get(i-1).optLong("end"))throw new Exception("백업 안에 겹치는 기록이 있어.");SQLiteDatabase d=getWritableDatabase();int count=0;d.beginTransaction();try{for(JSONObject r:clean){long s=r.getLong("start"),e=r.getLong("end");Cursor c=d.rawQuery("SELECT id,state FROM records WHERE start=? AND end=?",new String[]{""+s,""+e});long id=-1;boolean done=false;try{if(c.moveToFirst()){id=c.getLong(0);done=c.getString(1).equals("confirmed");}}finally{c.close();}if(done)continue;JSONObject v=new JSONObject(r.toString());v.put("id",id);save(v);count++;}d.setTransactionSuccessful();}finally{d.endTransaction();}return count;}
}
